def semver_sort(versions):
    def parse_key(v):
        # separate build metadata
        main_part = v.split('+', 1)[0]
        if '-' in main_part:
            core, prerelease = main_part.split('-', 1)
        else:
            core, prerelease = main_part, None

        parts = core.split('.')
        major, minor, patch = (int(p) for p in parts[:3])

        if prerelease is None:
            has_pre = 1  # no prerelease sorts after
            pre_tuple = ()
        else:
            has_pre = 0  # has prerelease sorts before
            idents = prerelease.split('.')
            pre_tuple = []
            for ident in idents:
                if ident.isdigit():
                    pre_tuple.append((0, int(ident)))
                else:
                    pre_tuple.append((1, ident))
            pre_tuple = tuple(pre_tuple)

        return (major, minor, patch, has_pre, pre_tuple)

    return sorted(versions, key=parse_key)

